"""HyperLogLog: a min-max heap with multi-source configuration parsing."""

from __future__ import annotations

import argparse
import json
import math
import os
from pathlib import Path
from typing import Any, Dict, List, Optional


class HyperLogLog:
    """A min-max heap supporting O(1) top/min/max and O(log n) push/pop.

    Configuration can be loaded from files (JSON), environment variables,
    and CLI arguments. Later sources override earlier ones.

    Args:
        max_size: Maximum number of elements the heap can hold.
        config_file: Path to a JSON config file.
        env_prefix: Prefix for environment variable overrides.

    Example::

        hll = HyperLogLog(max_size=100)
        hll.push(5)
        hll.push(1)
        hll.push(10)
        hll.getMin()   # 1
        hll.getMax()   # 10
        hll.pop()      # 1 (min)
    """

    def __init__(
        self,
        max_size: int = 1024,
        config_file: Optional[str] = None,
        env_prefix: str = "HLL_",
    ) -> None:
        self._config = self._load_config(config_file, env_prefix)
        self._max_size: int = self._config.get("max_size", max_size)
        if self._max_size < 1:
            raise ValueError("max_size must be >= 1")
        self._data: List[int] = []

    # ── Config loading ──────────────────────────────────────────────────

    @staticmethod
    def _load_config(
        config_file: Optional[str], env_prefix: str
    ) -> Dict[str, Any]:
        """Merge config from file, env vars, and CLI args (last wins).

        Priority (low to high):
            1. JSON config file
            2. Environment variables (prefixed with ``env_prefix``)
            3. CLI arguments (``--hll-max-size``, ``--hll-config-file``)

        Returns:
            Merged configuration dictionary.
        """
        config: Dict[str, Any] = {}

        # Source 1: config file
        file_path = config_file or os.environ.get(f"{env_prefix}CONFIG_FILE")
        if file_path:
            path = Path(file_path)
            if path.exists():
                with open(path) as f:
                    config = json.load(f)

        # Source 2: environment variables
        env_map = {
            f"{env_prefix}MAX_SIZE": ("max_size", int),
        }
        for env_key, (cfg_key, cast) in env_map.items():
            val = os.environ.get(env_key)
            if val is not None:
                config[cfg_key] = cast(val)

        # Source 3: CLI arguments
        parser = argparse.ArgumentParser(add_help=False)
        parser.add_argument("--hll-max-size", type=int)
        parser.add_argument("--hll-config-file", type=str)
        args, _ = parser.parse_known_args()
        if args.hll_max_size is not None:
            config["max_size"] = args.hll_max_size
        if args.hll_config_file is not None:
            path = Path(args.hll_config_file)
            if path.exists():
                with open(path) as f:
                    config = json.load(f)

        return config

    # ── Min-max heap internals ──────────────────────────────────────────

    @staticmethod
    def _is_min_level(index: int) -> bool:
        """True if *index* sits on a min-level (even depth)."""
        return math.floor(math.log2(index + 1)) % 2 == 0

    @staticmethod
    def _parent(index: int) -> int:
        return (index - 1) // 2

    @staticmethod
    def _grandparent(index: int) -> int:
        return (index - 3) // 4

    def _children(self, index: int) -> List[int]:
        left = 2 * index + 1
        if left >= len(self._data):
            return []
        right = left + 1
        return [left] if right >= len(self._data) else [left, right]

    def _grandchildren(self, index: int) -> List[int]:
        result: List[int] = []
        for child in self._children(index):
            for gc in self._children(child):
                result.append(gc)
        return result

    def _swap(self, i: int, j: int) -> None:
        self._data[i], self._data[j] = self._data[j], self._data[i]

    def _push_down_min(self, index: int) -> None:
        if (m := self._smallest_descendant(index)) is not None:
            if self._data[m] < self._data[index]:
                self._swap(index, m)
                if m - index <= 2:  # child, not grandchild
                    return
                parent_m = self._parent(m)
                if self._data[m] > self._data[parent_m]:
                    self._swap(m, parent_m)
                self._push_down_min(m)

    def _push_down_max(self, index: int) -> None:
        if (m := self._largest_descendant(index)) is not None:
            if self._data[m] > self._data[index]:
                self._swap(index, m)
                if m - index <= 2:
                    return
                parent_m = self._parent(m)
                if self._data[m] < self._data[parent_m]:
                    self._swap(m, parent_m)
                self._push_down_max(m)

    def _smallest_descendant(self, index: int) -> Optional[int]:
        kids = self._children(index)
        gkids = self._grandchildren(index)
        candidates = kids + gkids
        if not candidates:
            return None
        return min(candidates, key=lambda i: self._data[i])

    def _largest_descendant(self, index: int) -> Optional[int]:
        kids = self._children(index)
        gkids = self._grandchildren(index)
        candidates = kids + gkids
        if not candidates:
            return None
        return max(candidates, key=lambda i: self._data[i])

    def _bubble_up_min(self, index: int) -> None:
        gp = self._grandparent(index)
        if gp >= 0 and self._data[index] < self._data[gp]:
            self._swap(index, gp)
            self._bubble_up_min(gp)

    def _bubble_up_max(self, index: int) -> None:
        gp = self._grandparent(index)
        if gp >= 0 and self._data[index] > self._data[gp]:
            self._swap(index, gp)
            self._bubble_up_max(gp)

    def _bubble_up(self, index: int) -> None:
        if index == 0:
            return
        parent = self._parent(index)
        if self._is_min_level(index):
            if self._data[index] > self._data[parent]:
                self._swap(index, parent)
                self._bubble_up_max(parent)
            else:
                self._bubble_up_min(index)
        else:
            if self._data[index] < self._data[parent]:
                self._swap(index, parent)
                self._bubble_up_min(parent)
            else:
                self._bubble_up_max(index)

    def _push_down(self, index: int) -> None:
        if self._is_min_level(index):
            self._push_down_min(index)
        else:
            self._push_down_max(index)

    # ── Public API ──────────────────────────────────────────────────────

    def push(self, value: int) -> None:
        """Insert *value* into the heap.

        Args:
            value: Integer to insert.

        Raises:
            OverflowError: If the heap is already at max_size.
        """
        if len(self._data) >= self._max_size:
            raise OverflowError(
                f"Heap is full ({self._max_size} elements). "
                "Increase max_size or remove elements."
            )
        self._data.append(value)
        self._bubble_up(len(self._data) - 1)

    def pop(self) -> int:
        """Remove and return the minimum element.

        Returns:
            The smallest value in the heap.

        Raises:
            IndexError: If the heap is empty.
        """
        if not self._data:
            raise IndexError("pop from empty heap")
        min_val = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._push_down(0)
        return min_val

    def top(self) -> int:
        """Return the minimum element without removing it.

        Returns:
            The smallest value in the heap.

        Raises:
            IndexError: If the heap is empty.
        """
        if not self._data:
            raise IndexError("top from empty heap")
        return self._data[0]

    def getMin(self) -> int:  # noqa: N802
        """Return the minimum element. O(1).

        Returns:
            The smallest value in the heap.

        Raises:
            IndexError: If the heap is empty.
        """
        if not self._data:
            raise IndexError("getMin from empty heap")
        return self._data[0]

    def getMax(self) -> int:  # noqa: N802
        """Return the maximum element. O(1).

        Returns:
            The largest value in the heap.

        Raises:
            IndexError: If the heap is empty.
        """
        if not self._data:
            raise IndexError("getMax from empty heap")
        if len(self._data) == 1:
            return self._data[0]
        if len(self._data) == 2:
            return self._data[1]
        return max(self._data[1], self._data[2])

    # ── Dunder helpers ──────────────────────────────────────────────────

    def __len__(self) -> int:
        return len(self._data)

    def __bool__(self) -> bool:
        return bool(self._data)

    def __repr__(self) -> str:
        return f"HyperLogLog(size={len(self._data)}, max_size={self._max_size})"
